W = {'putih': '#FFFFFF', 'navy': '#051C2C', 'oranye': '#D9600B', 'merah': '#C8102E', 'slate': '#5B7A99', 'abu': '#6B7280', 'biru': '#2F86D1', 'coklat': '#8A6A2E'}
S = 96; n = 0; g = []
for nm, d in P.items():
    for wn, c in W.items():
        x, y = (n % 16) * S, (n // 16) * S
        g.append(f'<svg x="{x}" y="{y}" width="{S}" height="{S}" viewBox="0 0 24 24" fill="none" stroke="{c}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{d}</svg>')
        n += 1
rows = (n + 15) // 16
os.makedirs('ik', exist_ok=True)
open('ik/lembar.svg', 'w').write(f'<svg xmlns="http://www.w3.org/2000/svg" width="{16 * S}" height="{rows * S}">{"".join(g)}</svg>')
subprocess.run([sys.argv[1], '--headless', '--screenshot=ik/lembar.png', f'--window-size={16 * S},{rows * S}', '--default-background-color=00000000',
                '--hide-scrollbars', 'file://' + os.path.abspath('ik/lembar.svg')], check=True, capture_output=True)
im = Image.open('ik/lembar.png'); n = 0
for nm in P:
    for wn in W:
        x, y = (n % 16) * S, (n // 16) * S; im.crop((x, y, x + S, y + S)).save(f'ik/{nm}-{wn}.png'); n += 1
os.remove('ik/lembar.png'); os.remove('ik/lembar.svg'); print('ikon', n)
